class Solution:
    def calculate(self, expr: str) -> int:
        toks, num = [], None
        for c in expr:
            if c.isdigit():
                num = (num or 0) * 10 + int(c)
            elif c != " ":
                toks += [num, c]
                num = None
        toks.append(num)
        for ops in ("*/", "+-"):
            i = 1
            while i < len(toks):
                if toks[i] in ops:
                    a, op, b = toks[i - 1], toks[i], toks[i + 1]
                    if op == "*": r = a * b
                    elif op == "/": r = abs(a) // b * (1 if a >= 0 else -1)
                    elif op == "+": r = a + b
                    else: r = a - b
                    toks[i - 1:i + 2] = [r]
                else:
                    i += 2
        return toks[0]

