class Solution {
    public int calculate(String expr) {
        List<Object> toks = new ArrayList<>();
        int num = 0;
        for (char c : expr.toCharArray()) {
            if (Character.isDigit(c)) num = num * 10 + (c - '0');
            else if (c != ' ') { toks.add(num); toks.add(c); num = 0; }
        }
        toks.add(num);
        for (String ops : new String[] {"*/", "+-"}) {
            int i = 1;
            while (i < toks.size()) {
                char op = (Character) toks.get(i);
                if (ops.indexOf(op) < 0) { i += 2; continue; }
                int a = (Integer) toks.get(i - 1), b = (Integer) toks.get(i + 1);
                int r = op == '*' ? a * b : op == '/' ? a / b : op == '+' ? a + b : a - b;
                toks.subList(i - 1, i + 2).clear();
                toks.add(i - 1, r);
            }
        }
        return (Integer) toks.get(0);
    }
}

