class Solution {
public:
    int calculate(string& expr) {
        vector<int> nums;
        vector<char> ops;
        int num = 0;
        for (char c : expr) {
            if (isdigit(c)) num = num * 10 + (c - '0');
            else if (c != ' ') { nums.push_back(num); ops.push_back(c); num = 0; }
        }
        nums.push_back(num);
        for (string level : {"*/", "+-"}) {
            size_t i = 0;
            while (i < ops.size()) {
                char op = ops[i];
                if (level.find(op) == string::npos) { i++; continue; }
                int a = nums[i], b = nums[i + 1];
                nums[i] = op == '*' ? a * b : op == '/' ? a / b : op == '+' ? a + b : a - b;
                nums.erase(nums.begin() + i + 1);
                ops.erase(ops.begin() + i);
            }
        }
        return nums[0];
    }
};

