int calculate(char* expr) {
    int n = strlen(expr), cnt = 0, num = 0;
    int* nums = malloc((n + 1) * sizeof(int));
    char* ops = malloc(n + 1);
    for (int i = 0; i < n; i++) {
        char c = expr[i];
        if (c >= '0' && c <= '9') num = num * 10 + (c - '0');
        else if (c != ' ') { nums[cnt] = num; ops[cnt++] = c; num = 0; }
    }
    nums[cnt] = num;
    const char* levels[] = {"*/", "+-"};
    for (int lv = 0; lv < 2; lv++) {
        int i = 0;
        while (i < cnt) {
            char op = ops[i];
            if (!strchr(levels[lv], op)) { i++; continue; }
            int a = nums[i], b = nums[i + 1];
            nums[i] = op == '*' ? a * b : op == '/' ? a / b : op == '+' ? a + b : a - b;
            memmove(nums + i + 1, nums + i + 2, (cnt - i - 1) * sizeof(int));
            memmove(ops + i, ops + i + 1, cnt - i - 1);
            cnt--;
        }
    }
    int answer = nums[0];
    free(nums);
    free(ops);
    return answer;
}

