class Solution:
    def calculate(self, expr: str) -> int:
        stack, num, op = [], 0, "+"
        for c in expr + "+":
            if c == " ":
                continue
            if c.isdigit():
                num = num * 10 + int(c)
                continue
            if op == "+":
                stack.append(num)
            elif op == "-":
                stack.append(-num)
            elif op == "*":
                stack[-1] *= num
            else:
                q = abs(stack[-1]) // num
                stack[-1] = q if stack[-1] >= 0 else -q
            op, num = c, 0
        return sum(stack)

