        if (c >= '0' && c <= '9') { num = num * 10 + (c - '0'); continue; }
        if (op == '+') stack[top++] = num;
        else if (op == '-') stack[top++] = -num;
        else if (op == '*') stack[top - 1] *= num;
        else stack[top - 1] /= num;
        op = c;
        num = 0;
    }
    int sum = 0;
    for (int i = 0; i < top; i++) sum += stack[i];
    free(stack);
    return sum;
}

